import { normalizeAssistantCacheContent } from '../../../utils/cache-normalize.js';
function normalizeCacheMessage(message) {
    const { attachments, ...normalized } = message;
    if (message.role === 'assistant') {
        normalized.content = normalizeAssistantCacheContent(message.content);
    }
    return {
        ...normalized,
        ...(attachments && attachments.length > 0 ? { attachments } : {})
    };
}
export function getAutoCacheLookupHistory(currentHistory) {
    if (currentHistory.length <= 1) {
        return [];
    }
    return currentHistory.slice(0, -1).map(normalizeCacheMessage);
}
export function buildAutoCacheSaveHistory(currentHistory, assistantResponse) {
    return [
        ...currentHistory.map(normalizeCacheMessage),
        normalizeCacheMessage({
            role: 'assistant',
            content: assistantResponse
        })
    ];
}
